targets.clientTransformScript:
javascript(/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    if (api.item.value.isFavorite) {
        return {
            favorite: api.item.value,
            actionType: "delete"
        };
    } else {
        return {
            favorite: api.item.value,
            actionType: "upsert"
        };
    }
})

